import{_ as t,c as s,o as i,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"卷三·14","description":"易小帖 - 卷三·14","frontmatter":{"title":"卷三·14","description":"易小帖 - 卷三·14"},"headers":[],"relativePath":"classics/yixiaotie/082.md","filePath":"classics/yixiaotie/082.md"}'),o={name:"classics/yixiaotie/082.md"};function c(n,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"卷三·14",tabindex:"-1"},[r("卷三·14 "),e("a",{class:"header-anchor",href:"#卷三·14","aria-label":"Permalink to “卷三·14”"},"​")],-1),e("p",null,"卦位無數，蓍莖有數，故易之有數始於揲蓍。然其數則夫子自言之，無容後人增減者。其曰「乾之策二百一十有六」，謂揲蓍法以四莖起揲數，老陽數九，以四乘九則四九三十六為一陽之數。乾有六陽，則三六一百八十，又六六三十六，合得二百一十六策。又曰「坤之策百四十有四」，謂老陰數六，以四乘六，則四六二十四為一陰之數，坤有六陰，則二六一百二十，又四六二十四，合得一百四十四策。又曰「凡三百有六十，當期之數」，謂乾策二百一十六，與坤數一百四十四，共得三百六十，與律曆一期之數相值，故曰當，非謂易數必合曆數也。乃又曰「二篇之策萬有一千五百二十」，謂上下二經六十四卦，該有三百八十四爻，而陰陽各半，則陽爻一百九十二，每爻三十六，可得六千九百一十二策。陰爻一百九十二，每爻二十四，可得四千六百八策，合之為一萬一千五百二十。其雲當萬物之數，以無象可當，則取其盈數，約略指之曰萬物，其不得再指，曆數可驗也。宋人拾得舊儒凡卦皆反對一語，以為屯反為蒙只是屯卦，需反為訟只是需卦，於是將六十四卦中可反對者合併之，凡五十六卦，竟並作二十八卦，而以乾坤坎離頤大過中孚小過八卦不反對者通計之得三十六卦，乃即此三十六卦中計其爻該有二百一十六，於是二百一十六其六十之策共得一萬二千九百六十策，因繪圖立說，名為《周易六宮圖》而大斷其說曰「周易全數萬有二千九百六十策，當邵氏《皇極經世》十二萬九千六百策一元之數」*，是夫子之言非矣，且不知其以二百一十六乘六十之數，所謂六十者何數也？夫反對之例，創自文王，而夫子於《雜卦》言之，前儒又言之，原非宋人創說，可不必多方曲求，過作狡獪。若六十四卦則儼然在列，周官太卜三易明雲「連山、歸藏，周易其經卦皆八，其別卦皆六十有四」，而宋人敢曰周易三十六卦，《周易》全策，夫子明明指定之曰萬有一千五百二十當萬物之數，而宋人敢曰《周易》全策萬有二千九百六十當邵氏《皇極經世》一元之數，其離經叛道可謂極矣。羲文作易，未嘗為律曆設，其雲當一期之數，偶然以數適相當，故雲。觀其後祗曰萬物可知。若止作律算，盈萬累億，則一天文生能之，即不然，一會計吏能之，曾何足以難。儒者而愚者，輒以加一倍法為神奇，一似夫子翻有所未解者。故吾謂：律呂之學亡於備數，推易亦然，非虛語也。",-1)])])}const x=t(o,[["render",c]]);export{f as __pageData,x as default};
